const missionText = "This observatory is a shared workspace for noticing signals, collecting context, and turning scattered observations into clear, useful insight. It exists to help the project track what matters, preserve what has been learned, and coordinate follow-up so that discoveries become decisions rather than disappearing into the noise.\n";
const missionWrite = writeFile("mission.md", missionText);
display(missionWrite.ok ? "Created `mission.md` with a one-paragraph mission note." : `Could not create mission.md: ${missionWrite.error ?? "unknown error"}`);
